definition.text:
pilgrimage.6830 = {
	type = activity_event
	title = pilgrimage.6830.t
	desc = pilgrimage.6830.desc
	theme = pilgrimage_destination
	override_background = { reference = temple }
	left_portrait = {
		character = root
		triggered_animation = {
			trigger = {
				OR = {
					has_trait = cynical
					has_trait = lifestyle_reveler
				}
			}
			animation = boredom
		}
		animation = personality_zealous
	}
	artifact = {
		trigger = { exists = scope:votive_artifact }
		target = scope:votive_artifact
		position = lower_center_portrait
	}
	cooldown = { years = 1 }
	trigger = {
		has_activity_intent = reflection_intent
		NOT = { religion = religion:tengrism_religion }
	}
	immediate = {
		random_character_artifact = {
			limit = {
				is_important_artifact_trigger = no
				NOR = { 
					rarity = illustrious
					rarity = famed
				}
				artifact_durability < 50
				is_equipped = no
			}
			alternative_limit = {
				is_important_artifact_trigger = no
				NOR = { 
					rarity = illustrious
					rarity = famed
				}
				is_equipped = no
			}
			alternative_limit = {
				is_important_artifact_trigger = no
				is_equipped = no
			}
			alternative_limit = {
				is_important_artifact_trigger = no
			}
			save_scope_as = votive_artifact
		}
	}
	weight_multiplier = {
		base = 1
		modifier = {
			factor = 2
			OR = { #you're in a reflection journey
				has_activity_intent = reflection_intent
				scope:activity = {
					has_activity_option = {
						category = special_type
						option = pilgrimage_type_pious
					}
				}
			}
		}
	}
	#Pray
	option = {
		name = pilgrimage.6830.a
		pious_type_option_effect = yes
		add_piety = miniscule_piety_gain
		stress_and_fulfillment_impact = {
			base = medium_stress_impact_loss
			zealous = medium_stress_impact_loss
			arrogant = minor_stress_impact_gain
			cynical = medium_stress_impact_gain
		}
		ai_chance = {
			base = 100
			modifier = {
				factor = 0
				has_trait = arrogant
				has_trait = cynical
			}
		}
	}
	#Admire the architecture
	option = {
		name = pilgrimage.6830.b
		worldly_type_option_effect = yes
		if = {
			limit = { has_lifestyle = learning_lifestyle }
			add_learning_lifestyle_xp = minor_lifestyle_experience
		}
		random_list = {
			80 = {
				add_character_modifier = {
					modifier = architectural_interest_modifier
					years = 10
				}
			}
			20 = {
				add_learning_skill = 1
			}
		}
		stress_and_fulfillment_impact = {
			base = medium_stress_impact_loss
			zealous = medium_stress_impact_gain
		}
		ai_chance = {
			base = 100
			modifier = {
				factor = 0
				has_trait = zealous
			}
		}
	}
	#Make a donation
	option = {
		name = pilgrimage.6830.c
		trigger = {
			exists = scope:votive_artifact
			has_trait = pilgrim #Only pilgrim since you can't level up the hajj trait
			has_trait_xp = {
				trait = pilgrim
				value < 100
			}
		}
		custom_tooltip = pilgrimage.6830.c.tt
		pious_type_option_effect = yes
		add_piety = miniscule_piety_gain
		add_trait_xp = {
			trait = pilgrim
			value = 20
		}
		hidden_effect = { destroy_artifact = scope:votive_artifact }
		stress_and_fulfillment_impact = {
			base = medium_stress_impact_loss
			greedy = minor_stress_impact_gain
			avaricious = minor_stress_impact_gain
			cynical = medium_stress_impact_gain
		}
		ai_chance = {
			base = 100
			modifier = {
				factor = 0
				OR = {
					has_trait = greedy
					has_trait = avaricious
					has_trait = cynical
				}
			}
			modifier = {
				factor = 0
				OR = {
					scope:votive_artifact = {
						rarity = illustrious
					}
					scope:votive_artifact = {
						rarity = famed
					}
				}
			}
			modifier = {
				factor = 2
				has_trait = zealous
			}
		}
	}
}

common_helpers.text:
pious_type_option_effect = {
	involved_activity ?= {
		if = {
			limit = { 
				OR = {
					activity_has_pious_pilgrimage_type_trigger = yes
					#Hajj should also be considered a pious pilgrimage
					activity_has_hajj_pilgrimage_type_trigger = yes
				}
			}
			custom_tooltip = pilgrimage_pious_type_tt_positive
			activity_special_type_progression_major= yes
		}
	}
}

worldly_type_option_effect = {
	involved_activity ?= {
		if = {
			limit = { activity_has_worldly_pilgrimage_type_trigger = yes }
			custom_tooltip = pilgrimage_worldly_type_tt_positive
			activity_special_type_progression_major = yes
		}
	}
}
